class Solution {
    public int numberOfEmployeesWhoMetTarget(int[] hours, int target) {
        int count = 0;
        for (int h : hours) {
            if (h >= target) count++;
        }
        return count;
    }
}

import java.util.Arrays;

class Solution {
    public int numberOfEmployeesWhoMetTarget(int[] hours, int target) {
        Arrays.sort(hours);
        int lo = 0, hi = hours.length;
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            if (hours[mid] >= target) {
                hi = mid;
            } else {
                lo = mid + 1;
            }
        }
        return hours.length - lo;
    }
}
